export const foundations = [
  ['Typography', '<strong>Lexend</strong> for headings, numbers and buttons; <strong>Atkinson Hyperlegible</strong> (made for readers with low vision) for text. Both are served by OpenDoor itself (no calls to Google). Base 16 px, line height 1.5, h1 34 px; paragraphs at most about 70 characters wide.'],
  ['Layout', 'Content up to 81 rem (1,264 px) centred, as on the 1,440 px Figma frames. Find jobs uses two columns (20 rem filters + results) from 56 rem (896 px); job details, the employer page and dashboards use a main column and a side column. Below that everything stacks. Job cards stack their icon tile, text and button when the card is narrower than 30 rem – this also works at large text sizes.'],
  ['Shape and spacing', '8 px grid; corner radius 12 px (fields), 16 px (tables, alerts), 20 px (cards) and fully rounded pills (buttons, badges, tags); cards have a 2 px border.'],
  ['Buttons', 'Pill-shaped: primary (filled purple), secondary (purple outline), small, link-style, danger outline (red outline: Withdraw, Delete, Suspend, Not selected…) and danger (filled red, inside confirm dialogs). At least 52 px high (44 px small). Busy buttons keep focus and say what is happening ("Saving…").'],
  ['Status', 'Always icon + word + colour, never colour alone: ✓ success (green), ✕ danger (red), ⚠ warning (amber), ○ info (purple), – neutral (grey).'],
  ['Display settings', 'Text size 100 / 125 / 150 % (root font size), high contrast (darker text, borders and buttons, thicker focus ring) and reduced motion are saved to the account. Quiet mode (no sparkles or decoration, calm colours, no animation) and the compact menu stay on the device. Applied as <code>data-text-size</code>, <code>data-contrast</code>, <code>data-motion</code>, <code>data-quiet</code> and <code>data-menu</code> on <code>&lt;html&gt;</code>; the system "reduce motion" setting is also respected; in Windows forced colours the native checkboxes and radios come back.'],
  ['Responsive', 'Works at 320 px width and at 200 % text without sideways scrolling (checked again on October 14, 2026); wide tables scroll inside their own labelled box.'],
];

export const components = [
  { name: 'UtilityBar (display bar)', crop: 'utility-bar', purpose: 'Thin bar at the top of every page: "Skip to main content", "Text size (now Standard)" (cycles Standard → Large → Extra large), "High contrast", "Quiet mode" and "Compact menu" / "Show all links". Toggles say whether they are on (pressed state); each change is announced ("Quiet mode is on.").', notes: 'Signed in, text size and contrast are also saved to the account. The same choices are in Account → Display.' },
  { name: 'SiteHeader', crop: 'header', purpose: 'Role links on the left and right of the centred OpenDoor logo (links to the role\'s home); the current page is a filled pill. Signed in: Notifications with unread count, "Account" with initials, "Log out". When the full menu does not fit (narrow screen, large text, or Compact menu chosen) it shows the logo, a "Menu" button and Account; the Menu panel lists the links with icons, closes with Escape and returns focus to the button.', notes: 'The full menu is measured, so it never wraps onto two lines.' },
  { name: 'SiteFooter', crop: 'footer', purpose: 'Links "Privacy" and "Accessibility statement", "© 2026 OpenDoor", and the line "OpenDoor – inclusive hiring for persons with disabilities. Map data © OpenStreetMap contributors. Location lists from the Philippine Standard Geographic Code (PSGC)."', notes: '' },
  { name: 'Page and BackLink', purpose: 'Every screen starts with one h1, an optional subtitle and optional actions (Read aloud) and badge. Sets the browser tab title ("Find jobs – OpenDoor") and moves focus to the h1 when the address changes (not when only the search part changes, so typing in a filter keeps focus). "‹ Back to …" links return to where the user came from, filters included.', notes: 'Where two pages share a heading, the tab title is made unique.' },
  { name: 'Button', purpose: 'Button that stays focusable while unavailable (<code>aria-disabled</code> instead of <code>disabled</code>) and ignores repeated clicks while a request runs.', notes: 'Variants: primary, secondary, small, link, danger outline, danger.' },
  { name: 'Alert / ApiErrorAlert', crop: 'alert-success', purpose: 'Message box in four types (info, success, warning, error), each with an icon, a coloured border and a bold title. API errors show a plain-language message and a "Reference: …" request id for support.', notes: 'Results are announced politely; blocking errors assertively.' },
  { name: 'ErrorSummary', crop: 'error-summary', purpose: '"There is a problem" box above a form after a failed submit, listing every error as a link to its field. It takes focus.', notes: 'GOV.UK error-summary pattern; each field also shows its own error (red border and message) under the label.' },
  { name: 'Form fields', purpose: 'TextField, TextArea (with "N of M characters used" counter), SelectField, CheckboxField and RadioGroup (24 px custom boxes; inline or as whole-card choices). Label above, then hint, then error, then the input; required fields say "(required)" in text. "Show password" checkboxes on password forms.', notes: '<code>voice</code> adds the Speak button (VoiceInput).' },
  { name: 'Tabs', crop: 'tabs', purpose: 'ARIA tabs: Left/Right arrows, Home and End move between tabs; the open tab is kept in the address (<code>?tab=about</code>), so it can be linked. All panels stay loaded, so unsaved edits survive switching tabs.', notes: 'Used on Profile and Account.' },
  { name: 'WizardProgress', crop: 'wizard-progress', purpose: '"Step 2 of 4 · Description and place" heading with one bar per step (decorative). The heading takes focus on each step; the tab title says the step ("Post a new job (step 2 of 4)"). "Next" checks only the fields of that step; server errors send the user to the first step that has one.', notes: 'Used by Create account (3 steps) and Post a new job / Edit posting (4 steps).' },
  { name: 'AccommodationPicker', crop: 'accommodation-group', purpose: 'Grouped checkboxes for the accommodation types (Physical access, Communication, Work arrangement, Assistive technology, Support) with short descriptions and a live "N selected." line. In job postings, each checked item gets an optional "Details for …" input.', notes: 'Used for needs, posting accommodations (two columns) and the "must offer" search filter.' },
  { name: 'LocationPicker', crop: 'location-picker', purpose: 'Region → Province → City or municipality selects from the official PSGC lists (NCR has no provinces); hint "Choose the region first, then the city or municipality." Shows the saved place with a "Change location" button until the user edits it.', notes: 'Lists come from the Insights Service; a failed list is announced.' },
  { name: 'JobCard and SaveJobButton', crop: 'job-card', purpose: 'Search result: coloured icon tile, title link, company + Verified badge, "Full-time · On-site · Quezon City…", match badge, up to 3 accommodation tags (+N more), "Trust score 79% · Apply by …" or "Trust score not published yet (1 of 3 responses)". For job seekers a "Save" / "Saved" button on the right (pressed state; its name includes the job title).', notes: 'Also used on Saved jobs (with Remove) and the employer page.' },
  { name: 'MatchBadge', crop: 'match-badge', purpose: '"Meets all 3 of your needs" (green ✓) or "Meets 1 of your 3 needs" (purple ○). On job details an info alert below lists "Not mentioned in this posting: …".', notes: 'Only for job seekers who saved needs.' },
  { name: 'StatusBadge / VerifiedBadge', crop: 'status-table', purpose: 'Pill-shaped status with icon for applications, postings, registry checks and reports (see Appendix B). "✓ Verified employer" for checked companies.', notes: '' },
  { name: 'IconTile and StatCards', crop: 'stat-cards', purpose: 'Dashboard tiles: coloured icon tile, big number (Lexend) and label; a "View" link covers the whole tile and is named with the number ("View Submitted (2)"); admin queues say "Open queue".', notes: 'The tile draws the focus ring when its link is focused.' },
  { name: 'StatusTimeline', crop: 'timeline', purpose: '"Where it stands": Submitted → Reviewed → Decision, each with its date or "Waiting for employer"; the step being waited for is marked as current (<code>aria-current="step"</code>).', notes: 'Stacks on phones.' },
  { name: 'TrustScoreCard', crop: 'trust-card', purpose: '"79% of promised accommodations were delivered. Based on 3 responses." with a link "How trust scores work", or "Not published yet … (1 of 3 so far)". Optional table per accommodation (Delivered / Partly / Not delivered).', notes: 'Compact on the job page and dashboard; with the table on the employer and trust-score pages.' },
  { name: 'AccessibilitySnapshot', crop: 'snapshot', purpose: 'Insights mashup on the job page, as a closed card with "Show Workplace Accessibility Snapshot": location, "What the employer says", "What hired employees say", "Accessible places nearby" (transport stops, toilets, parking, other places with distance and wheelchair status), source note.', notes: 'Loads only when opened; failures never block the job page.' },
  { name: 'Dialog / ConfirmDialog / ReasonDialog', crop: 'confirm-dialog', purpose: 'Modal on the native <code>&lt;dialog&gt;</code>: traps focus, Escape closes, focus returns to the button that opened it. ConfirmDialog asks yes/no; ReasonDialog asks for a (required or optional) reason or note.', notes: 'Dangerous actions start with focus on Cancel and use a red confirm button.' },
  { name: 'NotificationsLink', purpose: 'Header link "Notifications" with a red count badge; its name says "Notifications 2 unread". Refreshes on every page change and after marking as read.', notes: '' },
  { name: 'AsyncContent, Loading, EmptyState, ResultCount, Pagination, ActionFeedback', purpose: 'Shared states: "Loading …" status line; error with "Try again"; empty state as a card with an icon tile, a title and the next step; announced result count ("4 postings"); pagination with chevrons ("Previous page", "Page 1 of 3", "Next page", 12 items per page); success/error message after an action.', notes: 'Unavailable pagination buttons stay focusable instead of disappearing.' },
  { name: 'ReadAloud <span class="tag tag--new">New</span>', purpose: '"Read this job aloud" button: reads the title and main content with the browser\'s own voice. While reading: "Pause reading" / "Resume reading" and "Stop reading".', notes: 'Hidden when the browser cannot speak. Nothing leaves the device.' },
  { name: 'WelcomeTour <span class="tag tag--new">New</span>', purpose: 'Onboarding dialog "Welcome to OpenDoor" in 3 steps for job seekers (Jobs that fit what you need · Your needs and your profile · Apply, then rate) or employers (Reach job seekers with disabilities · Set up your company and get verified · Post jobs and earn trust). Each step: icon tile, heading "Step 1 of 3 · …" that takes focus, progress bars, two short paragraphs; step 1 adds a tip about the display bar, Read aloud and Speak. Buttons "Next" / "Get started", "Back", "Skip the tour".', notes: 'Opens on the first page after the first sign-in (usually right after Create account). Skip, Escape and Get started all save it as done with the account. Can be opened again from the Get started list or Account → Getting started.' },
  { name: 'GetStarted <span class="tag tag--new">New</span>', purpose: '"Get started" card on the dashboards: "n of 4 done", a ✓ or an empty circle per step (with hidden "Done:" / "To do:"), a short hint and a button for each open step, "Show the welcome tour" and "Hide this list".', notes: 'Steps come from the user’s own data, so they tick themselves. Gone when all are done or hidden; Account → Getting started shows it again. Accounts that existed before October 14, 2026 and the demo accounts start with both done.' },
  { name: 'VoiceInput <span class="tag tag--new">New</span>', purpose: '"Speak" button under a text field; adds what the user says to the field until "Stop listening". First use shows a notice that Chrome/Edge send the audio to their speech service.', notes: 'Hidden where the browser has no speech recognition (e.g. Firefox) or no speech service (Brave). Browsers like Opera fail on the first try: "Voice input does not work in this browser. Use Chrome or Edge, or type instead." takes the button’s place (focus moves to it) and the browser is remembered.' },
];

